arguments.command:
cat > src/CheckoutPricing.Application/CheckoutService.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class CheckoutService
{
    public decimal CalculatePayableTotal(string customerTier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.IntegrationTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysNinetyFive()
    {
        var total = new CheckoutService().CalculatePayableTotal("Gold", 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | grep -E "Assert|Expected|Actual|Failed|Passed!|error" | head -20

